ST.xhtml:p:
RTrigger(CLK := bHomeEnable);

IF RTrigger.Q THEN
  nHomeState := 1;
  g_bZHomeDone := FALSE;
  bHomeEnable := FALSE;  
END_IF;


CASE nHomeState OF
  0:
    nHomeState := 0;
  1:
    g_ZHome.Position :=dHomePosition;
    g_ZHome.DISTANCE := dHomeOffset;
    g_ZHome.bCalibrationCam := g_bZAxisZero;
    IF nHomingMode = 0 THEN
      g_ZHome.HomingMode := 0;
    ELSIF nHomingMode = 1 THEN
      g_ZHome.HomingMode := 5;
    ELSIF nHomingMode = 2 THEN
      g_ZHome.HomingMode := 4;
    END_IF;
    g_ZHome.Execute := TRUE;

    IF g_ZHome.Done THEN
      g_ZHome.Execute := FALSE;
      nHomeState := 0;
      g_bZHomeDone := TRUE;     
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nHomeState := 20;
    END_IF;
    IF g_ZHome.CommandAborted OR g_ZHome.Error THEN
      g_ZHome.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  20:
    g_ZHome.Execute := FALSE;
    g_ZMoveAbs.Execute := FALSE;
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done  THEN
      g_ZMoveStop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  END_CASE;


g_nZHomeState:=nHomeState;(*Z轴回零状态机监控*)

(***界面上按了Z轴置零点按钮***)
IF g_bSetZZeroPos THEN
   g_ZHome.HomingMode := 4;
   g_ZHome.Position := 0.0;
   g_ZHome.DISTANCE := 0.0;
   g_ZHome.Execute := TRUE;  
   IF g_ZHome.DONE OR g_ZHome.ERROR THEN 
    g_bZHomeDone := TRUE;
    g_ZHome.Execute := FALSE; 
    g_bSetZZeroPos := FALSE; 
   END_IF;
END_IF;

(***界面上下发了去掉Z轴回零标志***)
IF g_bCleanZHomed THEN
   g_ZHome.HomingMode := 1;
   g_ZHome.Execute := TRUE; 
   g_bZHomeDone := FALSE; 
   IF g_ZHome.DONE OR g_ZHome.ERROR THEN 
    g_ZHome.Execute := FALSE; 
    g_bCleanZHomed := FALSE; 
   END_IF;
END_IF;


(*伺服断电恢复基准点*)
RTrigger2(CLK := g_bRecoverZDatumMark);
IF RTrigger2.Q THEN
  g_bRecoverZDatumMark := FALSE;
  nRecoverZDatumMarkState := 1;
END_IF;
CASE nRecoverZDatumMarkState OF
  1:
   g_ZHome.HomingMode := 4;
   g_ZHome.Position :=g_ZDatumMark1; (*恢复基准点坐标差值*)
   g_ZHome.Execute := TRUE;  
   IF  g_ZHome.DONE OR g_ZHome.ERROR THEN 
    g_bZHomeDone := TRUE;
    g_ZHome.Execute := FALSE; 
    g_bSetZZeroPos := FALSE;
    nRecoverZDatumMarkState := 0; 
   END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nHomeState := 0;
  g_bZHomeDone := TRUE;
  g_ZMoveStop.Execute := FALSE;
  g_ZHome.Execute := FALSE;
  g_ZMoveAbs.Execute := FALSE;
  g_bSetZZeroPos := FALSE;
  g_bCleanZHomed := FALSE; 
END_IF;
g_nZHomeMode := nHomingMode;
